const style = P.style, sp = P.speed;
const NW = style === 'polychrome' ? 3 : 1;
const NV = style === 'polychrome' ? 30 : 72;          // scatterers per wavelength
const LR = NW === 3 ? [0.86, 1.0, 1.19] : [1.0];      // k scales as 1/lambda -> grain size runs with colour

// ---- the diffuser: a fixed seeded set of scattering directions inside the
// collecting aperture. Grain size is pinned to ~5 buffer pixels so the speckle
// upscales as real macro grain instead of aliasing into pixel hash.
const grainPx = 3.4 + (1 - P.density) * 7.5;
const Kmax = 6.283185 * (BW / grainPx) / (0.55 + P.scale * 0.75);
