  S.akey = akey; S.kx = new Float64Array(NV); S.ky = new Float64Array(NV);
  S.ph0 = new Float64Array(NV); S.dph = new Float64Array(NV);
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  for (let k = 0; k < NV; k++) {
    const th = fr(k * 4 + 1) * 6.283185, rr = Math.sqrt(fr(k * 4 + 2));   // area-uniform over the disc
    let ax = Math.cos(th) * rr, ay = Math.sin(th) * rr;
    if (P.aperture === 'slit') ay *= 0.22;                 // slit pupil -> elongated grains
