      const sg = 0.045 + bb[2] * 0.10, dx = X - cx, dy = Y - cy;
      ps += damp * (0.5 + bb[2]) * Math.exp(-(dx * dx + dy * dy) / (sg * sg + 1e-6)) * Math.sin(K.t * 0.083 * sp + bb[3]);
