      let I = (re * re + im * im) * invN;                   // mean 1, exponential distribution
      I = 1 + (I - 1) * ctr;
      if (NW === 1) { cr = I; cg = I; cb = I; } else { if (w === 0) cb = I; else if (w === 1) cg = I; else cr = I; }
    }
