    } else if (style === 'ironbow') {
      const v = 0.15 + (1 - Math.exp(-Math.max(0, cr) * expo)) * 0.70;
      R = Math.min(255, (v * 1.5 + 0.05) * 255); G = Math.max(0, Math.min(255, (v * 1.2 - 0.28) * 255));
      B = Math.max(0, Math.min(255, (v * 1.55 + 0.03 - Math.max(0, v - 0.5) * 1.9) * 255));
